(function () {
  "use strict";
  if (sessionStorage.getItem("almumez-admin") !== "1") { location.replace("admin.html"); return; }
  const form = document.querySelector("[data-bundle-form]"), list = document.querySelector("[data-bundle-list]"), empty = document.querySelector("[data-bundle-empty]"), errorNode = document.querySelector("[data-bundle-error]");
  const products = StoreProducts.read(), language = window.AdminUI?.language || "ar", fields = form.elements;
  const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" }[char]));
  const label = (product) => typeof product.name === "object" ? product.name[language] || product.name.en || product.name.ar : product.name;
  const price = (product) => Number(StoreProducts.getEffectivePrice(product).price || 0);
  const money = (value) => `${Math.round(Number(value) || 0).toLocaleString("en-US")} EGP`;
  const selects = [fields.primaryId, fields.secondId, fields.thirdId];
  const options = `<option value="">اختر منتجًا</option>${products.map((product) => `<option value="${esc(product.id)}">${esc(label(product))} — ${money(price(product))}</option>`).join("")}`;
  selects.forEach((select) => select.innerHTML = options);
  const selectedProducts = () => selects.map((select) => products.find((product) => product.id === select.value)).filter(Boolean);
  const total = () => selectedProducts().reduce((sum, product) => sum + price(product), 0);
  function syncFromDiscount() { const value = total(); fields.originalTotal.value = money(value); fields.price.value = Math.max(0, value - Number(fields.discount.value || 0)); }
  function syncFromPrice() { const value = total(); fields.originalTotal.value = money(value); fields.discount.value = Math.max(0, value - Number(fields.price.value || 0)); }
  function resetForm() { form.reset(); fields.id.value = ""; fields.enabled.checked = true; fields.discount.value = 650; fields.price.value = ""; fields.originalTotal.value = "0 EGP"; errorNode.textContent = ""; }
  function render() { const bundles = StoreBundles.read(); list.innerHTML = bundles.map((bundle) => { const names = bundle.productIds.map((id) => products.find((product) => product.id === id)).filter(Boolean).map(label); return `<article><div><span class="material-symbols-outlined">redeem</span><div><strong>${esc(bundle.title?.[language] || bundle.title?.en)}</strong><small>${names.map(esc).join(" + ")}</small></div></div><div><b>${money(bundle.price)}</b><small>خصم ${money(bundle.discount)}</small></div><span class="admin-product-stock ${bundle.enabled ? "in" : "out"}">${bundle.enabled ? "مفعّلة" : "متوقفة"}</span><div class="admin-product-actions"><button type="button" data-edit="${esc(bundle.id)}" aria-label="تعديل"><span class="material-symbols-outlined">edit</span></button><button type="button" data-delete="${esc(bundle.id)}" aria-label="حذف"><span class="material-symbols-outlined">delete</span></button></div></article>`; }).join(""); empty.hidden = bundles.length > 0; }
  selects.forEach((select) => select.addEventListener("change", syncFromDiscount));
  fields.discount.addEventListener("input", syncFromDiscount); fields.price.addEventListener("input", syncFromPrice);
  form.addEventListener("reset", () => setTimeout(() => { fields.id.value = ""; fields.enabled.checked = true; fields.discount.value = 650; fields.price.value = ""; fields.originalTotal.value = "0 EGP"; errorNode.textContent = ""; }));
  form.addEventListener("submit", (event) => { event.preventDefault(); const ids = selects.map((select) => select.value), original = total(), finalPrice = Number(fields.price.value), discount = Number(fields.discount.value); if (ids.some((id) => !id) || new Set(ids).size !== 3) { errorNode.textContent = "اختر ثلاثة منتجات مختلفة."; return; } if (!(finalPrice > 0) || finalPrice > original || discount !== original - finalPrice) { errorNode.textContent = "راجع سعر الباقة والخصم؛ يجب أن يساوي السعر النهائي إجمالي المنتجات ناقص الخصم."; return; } const bundles = StoreBundles.read(), id = fields.id.value || `bundle-${Date.now()}`, bundle = { id, title:{ ar:fields.titleAr.value.trim(), en:fields.titleEn.value.trim() }, primaryId:fields.primaryId.value, productIds:ids, price:finalPrice, discount, enabled:fields.enabled.checked, createdAt:bundles.find((item) => item.id === id)?.createdAt }; try { StoreBundles.write([...bundles.filter((item) => item.id !== id), bundle]); resetForm(); render(); } catch (error) { errorNode.textContent = error?.name === "QuotaExceededError" ? "مساحة المتصفح ممتلئة؛ لم يتم حفظ الباقة." : "تعذر حفظ الباقة."; } });
  list.addEventListener("click", (event) => { const edit = event.target.closest("[data-edit]"), remove = event.target.closest("[data-delete]"), bundles = StoreBundles.read(), bundle = bundles.find((item) => item.id === (edit?.dataset.edit || remove?.dataset.delete)); if (!bundle) return; if (remove) { if (confirm("حذف هذه الباقة؟")) { StoreBundles.write(bundles.filter((item) => item.id !== bundle.id)); render(); } return; } fields.id.value = bundle.id; fields.titleAr.value = bundle.title.ar; fields.titleEn.value = bundle.title.en; fields.primaryId.value = bundle.primaryId; fields.secondId.value = bundle.productIds[1]; fields.thirdId.value = bundle.productIds[2]; fields.discount.value = bundle.discount; fields.price.value = bundle.price; fields.enabled.checked = bundle.enabled; fields.originalTotal.value = money(total()); form.scrollIntoView({ behavior:"smooth", block:"start" }); });
  document.querySelector("[data-admin-logout]").addEventListener("click", () => { sessionStorage.removeItem("almumez-admin"); location.href = "admin.html"; });
  resetForm(); render();
})();
